css:
:root {
  --access-background: #F7FAFC;
  --access-icon-background: #E1EBF2;
  --access-icon-color: #4C728C;

  --access-heading-color: #5C7B8F;
  --access-status-color: #213B4D;
  --access-description-color: #728898;

  --access-login-background: #35677E;
  --access-login-text: #FFFFFF;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--access-background) !important;
}

.user-access-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--access-background);
  pointer-events: none;
}

.user-access-svg {
  display: block;
  width: 100%;
  height: 100%;

  font-family: "Segoe UI", Arial, sans-serif;
  shape-rendering: geometricPrecision;
}

.access-background {
  fill: var(--access-background);
}

.access-icon-background {
  fill: var(--access-icon-background);
}

.access-icon {
  fill: none;
  stroke: var(--access-icon-color);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.access-heading {
  fill: var(--access-heading-color);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: 1.8px;
}

.access-status {
  fill: var(--access-status-color);
  font-size: 64px;
  font-weight: 700;
  letter-spacing: 0;
}

.access-description {
  fill: var(--access-description-color);
  font-size: 48px;
  font-weight: 400;
  letter-spacing: 0;
}

.access-login-background {
  fill: var(--access-login-background);
}

.access-login-icon {
  fill: none;
  stroke: var(--access-login-text);
  stroke-width: 5;
  stroke-linecap: square;
  stroke-linejoin: miter;
}

.access-login-text {
  fill: var(--access-login-text);
  font-size: 56px;
  font-weight: 600;
  letter-spacing: 0;
}
